using var client = new System.Net.Sockets.TcpClient();
using var deadline = new CancellationTokenSource(TimeSpan.FromMilliseconds(500));
await client.ConnectAsync("127.0.0.1", 7000, deadline.Token);
Console.WriteLine($"connected {client.Client.LocalEndPoint} -> {client.Client.RemoteEndPoint}");
var stream = client.GetStream();
byte[] tx = System.Text.Encoding.ASCII.GetBytes("STATUS?\n");
await stream.WriteAsync(tx, deadline.Token);
var received = new List<byte>();
byte[] buffer = new byte[64];
while (!received.Contains((byte)10)) {
    int n = await stream.ReadAsync(buffer, deadline.Token);
    if (n == 0) throw new EndOfStreamException("EOF before reply terminator");
    received.AddRange(buffer.AsSpan(0, n).ToArray());
    if (received.Count > 1024) throw new InvalidDataException("Reply exceeds lab limit");
}
